PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "phone" varchar not null, "username" varchar not null, "referral_code" varchar not null, "referred_by" integer, "is_verified" tinyint(1) not null default '0', "balance" numeric not null default '0', "coins_balance" numeric not null default '0', "status" varchar check ("status" in ('active', 'suspended')) not null default 'active', "is_admin" tinyint(1) not null default '0', foreign key("referred_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "otps" ("id" integer primary key autoincrement not null, "user_id" integer not null, "code" varchar not null, "expires_at" datetime not null, "attempts" integer not null default '0', "resend_attempts" integer not null default '0', "last_sent_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "contracts" ("id" integer primary key autoincrement not null, "name" varchar not null, "price" numeric not null, "benefits" text not null, "duration_days" integer not null default '30', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "file_path" varchar);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "transactions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "amount" numeric not null, "type" varchar check ("type" in ('deposit', 'withdrawal', 'commission', 'purchase')) not null, "status" varchar check ("status" in ('pending', 'approved', 'rejected', 'completed')) not null default 'pending', "description" varchar, "reference" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "user_contracts" ("id" integer primary key autoincrement not null, "user_id" integer not null, "contract_id" integer not null, "status" varchar check ("status" in ('active', 'expired', 'cancelled')) not null default 'active', "expires_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("contract_id") references "contracts"("id") on delete cascade);
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "users_phone_unique" on "users" ("phone");
CREATE UNIQUE INDEX "users_username_unique" on "users" ("username");
CREATE UNIQUE INDEX "users_referral_code_unique" on "users" ("referral_code");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
COMMIT;
